import { Mesh, PlaneGeometry, Object3D, Vector3, Euler, Color } from 'three/webgpu';
import * as tsl from 'three/tsl';
import { gsap } from 'gsap';
import { createTextObject } from '@/text';

export default function createNode(config, ctx) {
  // ---- Card Base ----
  const CARD_WIDTH = 2.4;
  const CARD_HEIGHT = 3.2;
  const BORDER_RADIUS = 0.06;
  const BORDER_THICK = 0.006;

  const geometry = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT, 1, 1);
  const uv = tsl.uv();

  // Rounded rect mask
  const halfSize = tsl.vec2(0.5, 0.5);
  const pos = tsl.sub(uv, halfSize);
  const q = tsl.abs(pos);
  const k = tsl.sub(q, tsl.vec2(halfSize.x - BORDER_RADIUS, halfSize.y - BORDER_RADIUS));
  const inside = tsl.max(k.x, k.y);
  const dist = tsl.length(tsl.max(k, tsl.vec2(0))) + tsl.min(tsl.max(inside, 0.0), 0.0) - BORDER_RADIUS;

  const mask = tsl.step(dist, 0.0);
  const borderMask = tsl.step(dist, BORDER_THICK);

  const surfaceColor = tsl.color('#16161d');
  const backgroundColor = tsl.color('#0b0b10');
  const borderColor = tsl.color('#2a2a33');

  const baseColor = tsl.mix(backgroundColor, surfaceColor, mask);
  const finalColor = tsl.mix(baseColor, borderColor, borderMask);

  const material = new tsl.MeshBasicNodeMaterial();
  material.colorNode = finalColor;

  const cardMesh = new Mesh(geometry, material);
  cardMesh.name = 'PricingCard';
  cardMesh.position.set(0, 0, 0);
  cardMesh.rotation.set(0, 0, 0);
  cardMesh.scale.set(1, 1, 1);

  // ---- Header Strip ----
  const headerGeom = new PlaneGeometry(CARD_WIDTH, 0.08);
  const headerMat = new tsl.MeshStandardNodeMaterial();
  headerMat.colorNode = tsl.color('#16161d');
  headerMat.metalnessNode = tsl.float(0.5);
  headerMat.roughnessNode = tsl.float(0.55);
  headerMat.clearcoatNode = tsl.float(0.2);
  headerMat.anisotropyNode = tsl.float(0.6);
  const headerMesh = new Mesh(headerGeom, headerMat);
  headerMesh.position.set(0, CARD_HEIGHT / 2 - 0.04, 0.001);
  cardMesh.add(headerMesh);

  // ---- Text Elements ----
  const texts = [];

  function addText(content, style, offsetY) {
    const txt = createTextObject(content, {
      fontFamily: style.family,
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
      color: style.color || '#e8ecf2',
      align: 'center',
      atlas: ctx.fontAtlas,
    });
    txt.position.set(0, offsetY, 0.002);
    cardMesh.add(txt);
    return txt;
  }

  // Tier name
  const tierStyle = {
    family: 'JetBrains Mono',
    fontSize: 20,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1.2,
    color: '#e8ecf2',
  };
  const tierY = CARD_HEIGHT / 2 - 0.5;
  texts.push(addText(config.textContent.tierName || 'ATELIER RESERVE', tierStyle, tierY));

  // Price
  const priceStyle = {
    family: 'Lora',
    fontSize: 62,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1,
    color: '#e8ecf2',
  };
  const priceY = tierY - 0.4;
  texts.push(addText(config.textContent.price || '$480', priceStyle, priceY));

  // Caption
  const captionStyle = {
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 400,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#e8ecf2',
  };
  const captionY = priceY - 0.25;
  texts.push(addText(config.textContent.caption || 'PER MONTH, BILLED ANNUALLY', captionStyle, captionY));

  // Feature rows
  const featureStyle = {
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: '#e8ecf2',
  };
  const firstFeatureY = captionY - 0.6;
  const featureGap = 0.375 + BORDER_THICK; // row height + hairline
  const featureTexts = [
    config.textContent.feature0 || 'Quarterly movement service',
    config.textContent.feature1 || 'Priority commission slots',
    config.textContent.feature2 || 'Private fitting lounge access',
    config.textContent.feature3 || 'Lifetime case refinishing',
  ];
  featureTexts.forEach((txt, i) => {
    const y = firstFeatureY - i * featureGap;
    texts.push(addText(txt, featureStyle, y));
  });

  // CTA Row (gradient plane with text)
  const ctaWidth = 1.4;
  const ctaHeight = 0.36;
  const ctaGeom = new PlaneGeometry(ctaWidth, ctaHeight);
  const uvCta = tsl.uv();
  const grad = tsl.mix(tsl.color('#ff4450'), tsl.color('#c1121f'), uvCta.y);
  const emissive = tsl.mul(tsl.color('#ff2a38'), tsl.float(1.5));
  const ctaMat = new tsl.MeshStandardNodeMaterial();
  ctaMat.colorNode = grad;
  ctaMat.emissiveNode = emissive;
  const ctaMesh = new Mesh(ctaGeom, ctaMat);
  ctaMesh.position.set(0, -CARD_HEIGHT / 2 + 0.5, 0.003);
  cardMesh.add(ctaMesh);

  const ctaLabelStyle = {
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1,
    color: '#0b0b10',
  };
  const ctaLabel = createTextObject(
    config.textContent.ctaLabel || 'JOIN THE RESERVE',
    { ...ctaLabelStyle, align: 'center', atlas: ctx.fontAtlas }
  );
  ctaLabel.position.set(0, 0, 0.001);
  ctaMesh.add(ctaLabel);

  // ---- Animations ----
  const timelines = [];

  // Weighted-settle on card mount
  const settle = gsap.timeline({ paused: true });
  settle.from(cardMesh.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });
  settle.play();
  timelines.push(settle);

  // Feature rows stagger fade-up
  const featureTimeline = gsap.timeline({ paused: true });
  texts.slice(5).forEach((obj, i) => {
    obj.visible = false;
    featureTimeline.fromTo(
      obj,
      { y: obj.position.y + 0.2, opacity: 0 },
      {
        y: obj.position.y,
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onStart: () => (obj.visible = true),
        delay: i * 0.08,
      },
      0
    );
  });
  featureTimeline.play();
  timelines.push(featureTimeline);

  // CTA press interaction
  const ctaHandlers = {
    pointerdown: () => {
      gsap.to(ctaMesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
        onComplete: () => {
          gsap.to(ctaMesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.12,
            ease: 'elastic.out(1,0.3)',
          });
        },
      });
    },
  };
  ctaMesh.userData.handlers = ctaHandlers;

  // ---- Cleanup ----
  cardMesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    headerGeom.dispose();
    headerMat.dispose();
    ctaGeom.dispose();
    ctaMat.dispose();
    timelines.forEach((tl) => tl.kill());
    // Dispose text objects
    texts.forEach((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
    if (ctaLabel.geometry) ctaLabel.geometry.dispose();
    if (ctaLabel.material) ctaLabel.material.dispose();
  };

  // Apply any cinematic primitives listed (none in this spec)
  // (placeholder for future primitives)
  // if (config.cinematicPrimitives) {
  //   config.cinematicPrimitives.forEach(p => {
  //     const fn = ctx.primitives[p.name];
  //     if (fn) fn(cardMesh, p.params);
  //   });
  // }

  // Position, rotation, scale from config if provided
  if (config.position) cardMesh.position.copy(new Vector3(...config.position));
  if (config.rotation) cardMesh.rotation.copy(new Euler(...config.rotation));
  if (config.scale) cardMesh.scale.copy(new Vector3(...config.scale));

  return cardMesh;
}
